def start_battle(foes, bg=None, can_run=True, music=None):
    global battle_result
    es = []
    counts = {}
    for k in foes:
        e = dict(ENEMIES[k])
        counts[k] = counts.get(k, 0) + 1
        e["key"] = k
        e["mhp"] = e["hp"]
        e["flash"] = 0
        es.append(e)
    for e in es:
        if counts[e["key"]] > 1:
            counts[e["key"]] = counts[e["key"]]
    B.clear()
    B.update({"foes": es, "bg": bg, "can_run": can_run, "phase": "command", "actor": 0, "orders": [], "queue": [], "msg": "", "sub": None, "pending": None, "shake": 0, "won_xp": 0, "won_gold": 0, "turn": 1})
    battle_result = None
    first = alive(party)
    B["actor"] = party.index(first[0]) if first else 0
    names = {}
    for e in es:
        names[e["name"]] = names.get(e["name"], 0) + 1
    B["msg"] = "  ".join(("%d %ss" % (v, k) if v > 1 else k) for k, v in names.items()) + (" appear!" if len(es) > 1 else " appears!")
    if music:
        renpy.play(music, channel="music", loop=True)
def cur_actor():
    return party[B["actor"]]
def next_actor():
    i = B["actor"] + 1
    while i < len(party) and party[i]["hp"] <= 0:
        i += 1
    if i >= len(party):
        run_turn()
    else:
        B["actor"] = i
        B["phase"] = "command"
        B["sub"] = None
def cmd(c):
    bsnd("select")
    a = cur_actor()
    if c == "fight":
        if len(alive(B["foes"])) == 1:
            order("fight", alive(B["foes"])[0])
        else:
            B["pending"] = ("fight", None)
            B["phase"] = "target"
    elif c == "magic":
        if not a["spells"]:
            B["msg"] = a["name"] + " knows no techniques."
            return
        B["sub"] = "magic"
    elif c == "item":
        if not [k for k, n in inventory.items() if n > 0]:
            B["msg"] = "There are no items."
            return
        B["sub"] = "item"
    elif c == "talk":
        order("talk", None)
    elif c == "run":
        order("run", None)
def pick_spell(k):
    sp = SPELLS[k]
    a = cur_actor()
    if a["mp"] < sp["mp"]:
        B["msg"] = "Not enough MP."
        return
    choose_target(("magic", k), sp["target"])
def pick_item(k):
    choose_target(("item", k), ITEMS[k]["target"])
def choose_target(pending, target):
    B["sub"] = None
    if target == "enemy":
        if len(alive(B["foes"])) == 1:
            order(pending[0], alive(B["foes"])[0], pending[1])
        else:
            B["pending"] = pending
            B["phase"] = "target"
    elif target == "ally":
        B["pending"] = pending
        B["phase"] = "ally"
    else:
        order(pending[0], None, pending[1])
def pick_target(t):
    p = B["pending"]
    B["pending"] = None
    order(p[0], t, p[1])
def cancel():
    B["sub"] = None
    B["pending"] = None
    B["phase"] = "command"
def order(kind, target, what=None):
    B["orders"].append({"who": cur_actor(), "kind": kind, "target": target, "what": what})
    next_actor()
def say_(text, fx=None):
    B["queue"].append((text, fx))
def dmg(att, dfn):
    base = att["atk"] - dfn["df"] // 2
    v = max(1, int(base * (0.8 + 0.4 * renpy.random())))
    crit = renpy.random() < 1.0 / 16
    return (v * 2 if crit else v), crit
def hit(target, n, enemy_side):
    def f():
        target["hp"] = max(0, target["hp"] - n)
        if enemy_side:
            target["flash"] = 3
            bsnd("hit")
        else:
            B["shake"] = 1
            renpy.shake(0.35, 10)
            bsnd("hurt")
    return f
def heal_fx(target, n):
    def f():
        target["hp"] = min(target["mhp"], target["hp"] + n)
        bsnd("magic")
    return f
def run_turn():
    B["phase"] = "resolve"
    acts = list(B["orders"])
    for e in alive(B["foes"]):
        acts.append({"who": e, "kind": "enemy"})
    acts.sort(key=lambda a: -(a["who"]["agi"] + randint(0, 4)))
    B["orders"] = []
    for a in acts:
        act(a)
    say_(None, end_of_turn)
    B["msg"] = ""
    battle_next()
def act(a):
    w = a["who"]
    if w["hp"] <= 0:
        return
    if a["kind"] == "fight":
        t = a["target"]
        if t is None or t["hp"] <= 0:
            al = alive(B["foes"])
            if not al:
                return
            t = al[0]
        if renpy.random() < 0.06 + max(0, t["agi"] - w["agi"]) * 0.02:
            say_("%s attacks!  Missed!" % w["name"], lambda: bsnd("miss"))
            return
        n, crit = dmg(w, t)
        say_("%s attacks!%s  %s takes %d damage." % (w["name"], "  Critical hit!" if crit else "", t["name"], n), hit(t, n, True))
        say_(None, check_dead(t))
    elif a["kind"] == "magic":
        sp = SPELLS[a["what"]]
        if w["mp"] < sp["mp"]:
            say_("%s has no MP left." % w["name"])
            return
        w["mp"] -= sp["mp"]
        if sp["kind"] == "heal":
            t = a["target"] or w
            n = sp["power"] + randint(0, 4)
            say_("%s uses %s!  %s recovers %d HP." % (w["name"], sp["name"], t["name"], n), heal_fx(t, n))
        else:
            ts = alive(B["foes"]) if sp["target"] == "all" else [a["target"] if a["target"] and a["target"]["hp"] > 0 else (alive(B["foes"]) or [None])[0]]
            say_("%s uses %s!" % (w["name"], sp["name"]), lambda: renpy.fx("glow", amount=1.5, duration=0.5) or bsnd("magic"))
            for t in ts:
                if t is None:
                    continue
                n = sp["power"] + randint(0, 6) - t["df"] // 4
                say_("%s takes %d damage." % (t["name"], n), hit(t, max(1, n), True))
                say_(None, check_dead(t))
    elif a["kind"] == "item":
        it = ITEMS[a["what"]]
        if inventory.get(a["what"], 0) <= 0:
            return
        inventory[a["what"]] -= 1
        if it["kind"] == "heal":
            t = a["target"] or w
            say_("%s uses a %s.  %s recovers %d HP." % (w["name"], it["name"], t["name"], it["power"]), heal_fx(t, it["power"]))
        elif it["kind"] == "escape":
            say_("%s uses an %s!" % (w["name"], it["name"]), lambda: B.update({"fled": True}))
    elif a["kind"] == "talk":
        e = (alive(B["foes"]) or [None])[0]
        line = e and e.get("talk")
        say_("%s talks to %s." % (w["name"], e["name"] if e else "nobody"))
        say_(line or "It doesn't respond.")
    elif a["kind"] == "run":
        if not B["can_run"]:
            say_("There's no escape!")
            return
        fast = max(x["agi"] for x in alive(B["foes"])) if alive(B["foes"]) else 0
        if renpy.random() < 0.5 + (w["agi"] - fast) * 0.06:
            say_("%s's party runs away!" % w["name"], lambda: B.update({"fled": True}))
        else:
            say_("%s tries to run... but can't get away!" % w["name"])
    elif a["kind"] == "enemy":
        al = alive(party)
        if not al:
            return
        if w.get("flees") and renpy.random() < w["flees"]:
            say_("%s runs away." % w["name"], lambda: w.update({"hp": 0, "fled": 1}))
            return
        sp = [s for s in w.get("spells", []) if SPELLS[s]["kind"] == "damage" and w["mp"] >= SPELLS[s]["mp"]]
        t = choice(al)
        if sp and renpy.random() < 0.35:
            s = SPELLS[choice(sp)]
            w["mp"] -= s["mp"]
            n = max(1, s["power"] + randint(0, 4) - t["df"] // 4)
            say_("%s casts %s!  %s takes %d damage." % (w["name"], s["name"], t["name"], n), hit(t, n, False))
        else:
            n, crit = dmg(w, t)
            say_("%s attacks!%s  %s takes %d damage." % (w["name"], "  A terrible blow!" if crit else "", t["name"], n), hit(t, n, False))
        say_(None, check_dead_member(t))
def check_dead(t):
    def f():
        if t["hp"] <= 0 and not t.get("dead_said"):
            t["dead_said"] = 1
            B["queue"].insert(0, ("%s is defeated!" % t["name"], None))
            B["won_xp"] += t["xp"]
            B["won_gold"] += t["gold"]
    return f
def check_dead_member(t):
    def f():
        if t["hp"] <= 0 and not t.get("dead_said"):
            t["dead_said"] = 1
            B["queue"].insert(0, ("%s has fallen!" % t["name"], None))
    return f
def end_of_turn():
    for m in party:
        m.pop("dead_said", None)
    if B.get("fled"):
        finish("run")
    elif not alive(B["foes"]):
        win()
    elif not alive(party):
        B["queue"].append(("The party has been defeated...", lambda: bsnd("lose")))
        B["queue"].append((None, lambda: finish("lose")))
    else:
        B["turn"] += 1
        B["phase"] = "command"
        B["actor"] = party.index(alive(party)[0])
        B["msg"] = ""
def win():
    global gold
    bsnd("win")
    xp, g = B["won_xp"], B["won_gold"]
    gold += g
    B["phase"] = "resolve"
    B["queue"].append(("Victory!  %d experience points.  %d meseta." % (xp, g), None))
    for m in alive(party):
        m["xp"] += xp
        while m["lvl"] + 1 < len(XP_TABLE) and m["xp"] >= XP_TABLE[m["lvl"] + 1]:
            m["lvl"] += 1
            gr = m["growth"]
            for k in ("atk", "df", "agi"):
                m[k] += gr.get(k, 1)
            m["mhp"] += gr.get("hp", 4)
            m["mmp"] += gr.get("mp", 1)
            m["hp"] = m["mhp"]
            m["mp"] = m["mmp"]
            B["queue"].append(("%s is now level %d!" % (m["name"], m["lvl"]), lambda: bsnd("magic")))
    for e in B["foes"]:
        if e.get("drops") and renpy.random() < 0.3:
            give_item(e["drops"])
            B["queue"].append(("Found a %s." % ITEMS[e["drops"]]["name"], None))
    B["queue"].append((None, lambda: finish("win")))
def finish(result):
    global battle_result
    battle_result = result
    B["phase"] = "done"
    for e in B["foes"]:
        e["flash"] = 0
    raise _Ctl("return", result)
def battle_next():
    """Show the next queued message (applying its effect). Called by a timer and by taps."""
    while B["queue"]:
        text, fx = B["queue"].pop(0)
        if fx:
            fx()
        if text:
            B["msg"] = text
            return
        if B["phase"] != "resolve":
            return
def battle_tick():
    for e in B["foes"]:
        if e["flash"]:
            e["flash"] -= 1
    if B.get("phase") == "resolve":
        battle_next()
def foe_label():
    names = []
    for e in alive(B["foes"]):
        if e["name"] not in names:
            names.append(e["name"])
    return names
MG = {}
MG_STYLE = {"font": "sans-serif", "accent": "#ff6fa5", "ok": "#4ade80", "bad": "#ff4a5a", "panel": "#0b0910ee", "text": "#ffffff"}
MG_SOUNDS = {}
MG_DT = 0.033
def mg_snd(k):
    s = MG_SOUNDS.get(k)
    if s:
        renpy.play(s)
def mg_setup(kind, **kw):
    MG.clear()
    MG.update({"kind": kind, "t": 0.0, "done": None, "msg": kw.get("prompt", ""), "end_t": 0.0})
    if kind == "qte":
        MG.update({"keys": kw.get("keys", "ZXC"), "count": kw.get("count", 5), "time": kw.get("time", 1.3), "i": 0})
        mg_qte_next()
    elif kind == "mash":
        MG.update({"target": kw.get("target", 25), "time": kw.get("time", 5.0), "key": kw.get("key", " "), "n": 0.0})
    elif kind == "timing":
        MG.update({"rounds": kw.get("rounds", 3), "speed": kw.get("speed", 1.0), "zone": kw.get("zone", 0.16), "i": 0, "pos": 0.0, "dir": 1})
        mg_timing_zone()
    elif kind == "keypad":
        MG.update({"code": str(kw.get("code", "1234")), "tries": kw.get("tries", 3), "entry": ""})
    elif kind == "memory":
        p = kw.get("pairs", 6)
        faces = kw.get("faces") or [None] * p
        deck = []
        for i in range(p):
            deck += [i, i]
        for i in range(len(deck) - 1, 0, -1):
            j = randint(0, i)
            deck[i], deck[j] = deck[j], deck[i]
        MG.update({"deck": deck, "faces": faces, "open": [], "found": [], "moves": 0, "limit": kw.get("moves"), "hide_at": None})
    elif kind == "slide":
        n = kw.get("size", 3)
        tiles = list(range(n * n))
        MG.update({"n": n, "tiles": tiles, "image": kw.get("image")})
        blank = n * n - 1
        for _ in range(kw.get("shuffle", 60)):
            nb = mg_slide_neighbours(tiles.index(blank))
            mg_slide_swap(choice(nb), quiet=True)
    elif kind == "simon":
        MG.update({"seq": [randint(0, 3) for _ in range(kw.get("length", 5))], "shown": 0, "lit": -1, "input": [], "phase": "show", "step_t": 0.0, "len": 1})
def mg_end(ok, msg=None):
    if MG.get("done") is not None:
        return
    MG["done"] = bool(ok)
    MG["end_t"] = MG["t"]
    if msg:
        MG["msg"] = msg
    mg_snd("win" if ok else "lose")
def mg_tick():
    MG["t"] += MG_DT
    k = MG["kind"]
    if MG["done"] is not None:
        if MG["t"] - MG["end_t"] > 1.1:
            raise _Ctl("return", MG["done"])
        return
    if k == "qte":
        if MG["t"] - MG["start"] > MG["time"]:
            mg_snd("bad")
            mg_end(False, "Too slow!")
    elif k == "mash":
        MG["n"] = max(0.0, MG["n"] - MG_DT * 1.2)
        if MG["t"] > MG["time"]:
            mg_end(False, "Not strong enough...")
    elif k == "timing":
        MG["pos"] += MG["dir"] * MG_DT * MG["speed"] * (1.0 + 0.35 * MG["i"])
        if MG["pos"] > 1.0:
            MG["pos"], MG["dir"] = 1.0, -1
        if MG["pos"] < 0.0:
            MG["pos"], MG["dir"] = 0.0, 1
    elif k == "memory":
        if MG["hide_at"] is not None and MG["t"] >= MG["hide_at"]:
            MG["open"] = []
            MG["hide_at"] = None
    elif k == "simon":
        mg_simon_tick()
def mg_qte_next():
    MG["want"] = MG["keys"][randint(0, len(MG["keys"]) - 1)]
    MG["start"] = MG["t"]
    MG["slot"] = (randint(300, 980), randint(220, 460))
def mg_qte_press(k):
    if MG["done"] is not None:
        return
    if k.upper() == MG["want"].upper() or k == "tap":
        mg_snd("good")
        MG["i"] += 1
        if MG["i"] >= MG["count"]:
            mg_end(True, "Done!")
        else:
            mg_qte_next()
    else:
        mg_snd("bad")
        mg_end(False, "Wrong key!")
def mg_mash():
    if MG["done"] is not None:
        return
    MG["n"] += 1
    mg_snd("tick")
    if MG["n"] >= MG["target"]:
        mg_end(True, "Made it!")
def mg_timing_zone():
    z = MG["zone"] * (1.0 - 0.15 * MG["i"])
    c = 0.15 + renpy.random() * (0.85 - z)
    MG["zlo"], MG["zhi"] = c, c + z
def mg_timing_stop():
    if MG["done"] is not None:
        return
    if MG["zlo"] <= MG["pos"] <= MG["zhi"]:
        mg_snd("good")
        MG["i"] += 1
        if MG["i"] >= MG["rounds"]:
            mg_end(True, "Click!")
        else:
            mg_timing_zone()
    else:
        mg_snd("bad")
        mg_end(False, "Snap!")
def mg_key(d):
    if MG["done"] is not None:
        return
    mg_snd("tick")
    if d == "C":
        MG["entry"] = ""
    elif d == "OK":
        if MG["entry"] == MG["code"]:
            mg_end(True, "ACCESS GRANTED")
        else:
            MG["tries"] -= 1
            MG["entry"] = ""
            mg_snd("bad")
            if MG["tries"] <= 0:
                mg_end(False, "LOCKED OUT")
            else:
                MG["msg"] = "WRONG CODE  (%d left)" % MG["tries"]
    elif len(MG["entry"]) < len(MG["code"]):
        MG["entry"] += d
def mg_flip(i):
    if MG["done"] is not None or i in MG["found"] or i in MG["open"] or MG["hide_at"] is not None:
        return
    mg_snd("tick")
    MG["open"].append(i)
    if len(MG["open"]) == 2:
        MG["moves"] += 1
        a, b = MG["open"]
        if MG["deck"][a] == MG["deck"][b]:
            MG["found"] += [a, b]
            MG["open"] = []
            mg_snd("good")
            if len(MG["found"]) == len(MG["deck"]):
                mg_end(True, "All pairs in %d moves!" % MG["moves"])
        else:
            MG["hide_at"] = MG["t"] + 0.8
        if MG["limit"] and MG["moves"] >= MG["limit"] and MG["done"] is None and len(MG["found"]) < len(MG["deck"]):
            mg_end(False, "Out of moves.")
def mg_slide_neighbours(i):
    n = MG["n"]
    x, y = i % n, i // n
    out = []
    for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
        if 0 <= x + dx < n and 0 <= y + dy < n:
            out.append((y + dy) * n + x + dx)
    return out
def mg_slide_swap(i, quiet=False):
    t = MG["tiles"]
    blank = MG["n"] * MG["n"] - 1
    b = t.index(blank)
    if i not in mg_slide_neighbours(b):
        return
    t[i], t[b] = t[b], t[i]
    if not quiet:
        mg_snd("tick")
        if t == list(range(len(t))):
            mg_end(True, "Solved!")
def mg_simon_tick():
    if MG["phase"] != "show":
        return
    MG["step_t"] += MG_DT
    k = int(MG["step_t"] / 0.6)
    if k >= MG["len"]:
        if MG["step_t"] > MG["len"] * 0.6 + 0.2:
            MG["phase"], MG["lit"], MG["input"] = "input", -1, []
        else:
            MG["lit"] = -1
        return
    MG["lit"] = MG["seq"][k] if (MG["step_t"] % 0.6) < 0.4 else -1
def mg_simon_press(i):
    if MG["phase"] != "input" or MG["done"] is not None:
        return
    MG["input"].append(i)
    MG["lit"] = i
    if MG["seq"][len(MG["input"]) - 1] != i:
        mg_end(False, "Wrong!")
        return
    mg_snd("good")
    if len(MG["input"]) == MG["len"]:
        if MG["len"] == len(MG["seq"]):
            mg_end(True, "Perfect!")
        else:
            MG["len"] += 1
            MG["phase"], MG["step_t"] = "show", -0.5
